def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [row[0] for row in grid]

    for period in range(1, h + 1):
        pattern = {}
        valid = True
        for i, color in enumerate(rows):
            if color != 0:
                phase = i % period
                if phase in pattern and pattern[phase] != color:
                    valid = False
                    break
                pattern[phase] = color
        if valid:
            return [
                [pattern.get(i % period, rows[i])] * w
                for i in range(h)
            ]

    return grid
